#include <windows.h>

BOOL MyCreateRemoteThread(DWORD dwProcessID,DWORD dwProcAddr)

{

HANDLE hProcess;

HANDLE hThread;

DWORD dwThreadID;

hProcess = 0;

//1. 获取进程句柄

hProcess = OpenProcess(PROCESS_ALL_ACCESS,FALSE,dwProcessID);

if(hProcess == NULL)

{

OutputDebugString("OpenProcess Error! \n");

return FALSE;

}

//2. 创建远程线程

