								if ((i[4] < 4) || (num[5] != 0))
								{
									left = 0;
									right = num[1];
									sign = 1;
									for (j = 1; j <= 4; j++)
									{
										switch (oper[i[j]])
										{
										case '+':
											left = left + sign * right;
											sign = 1;
											right = num[j + 1];
											break;
										case '-':
											left = left + sign * right;
											sign = -1;
											right = num[j + 1];
											break;
										case '*':
											right = right * num[j + 1];
											break;
										case '/':
											right = right / num[j + 1];
											break;

										}
									}
									if (left + sign * right == result)
									{
										count++;
										printf("%3d: ", count);
										for (j = 1; j <= 4; j++)
										{
											printf("%d%c", num[j], oper[i[j]]);
										}
										printf("%d=%d\n", num[5], result);
									}
								}
							}
						}
					}
				}
			}
		}
	}
	if (count == 0)
	{
		printf("没有找到符合结果的方法\n");
	}
	getchar();
	return 0;
}

