}


//##--------------------------------------------分治算法
//分解、求解、和并
//例题：赛程安排，有八位选手比赛，每位逐对的进行比赛，要求每天每位选手都必须比一场，怎么安排日程最短？
int a[MAXN + 1][MAXN + 1] = { 0 };
void grouping(int k, int n)//处理编号x开始的n个选手的日程
{
	int i, j;
	if (n == 2)
	{
		a[k][1] = k;//参赛选手的编号
		a[k][2] = k + 1;//对阵选手编号
		a[k + 1][1] = k + 1;//参赛选手的编号
		a[k + 1][2] = k;//对阵选手的编号
	}
	else
	{
		grouping(k, n / 2);
		grouping(k + n / 2, n / 2);
		for (i = k; i < k + n / 2; i++)//填充右上角
		{
			for (j = n / 2 + 1; j <= n; j++)
			{
				a[i][j] = a[i + n / 2][j - n / 2];
			}
		}
		for (i = k + n / 2; i < k + n; i++)//填充右下角
		{
			for (j = n / 2+1; j <= n; j++)
			{
				a[i][j] = a[i - n / 2][j - n / 2];
			}
		}
	}
}
