	float m;
	printf("请输入找零的金额：");
	scanf("%f", &m);
	exchange((int)100 * m);
	printf("\n%.2f元零钱的组成：\n", m);
	for (i = 0; i < MAXM; i++)
	{
		if (num[i] > 0)
		{
			printf("%6.2f：%d张\n", (float)parvalue[i] / 100.0, num[i]);
		}
	}
	getchar();
	return 0;
}

