	char telephone[15];
	char mobile[12];
}DATA;


typedef struct Node
{
	DATA data;
	struct Node* next;
}ChainListType;

ChainListType* ChainListAddFirst(ChainListType* head, DATA data)
{
	ChainListType* node;
	if (!(node = (ChainListType*)malloc(sizeof(ChainListType))))
	{
		printf("为保存结点数据申请内存失败！\n");
		return NULL;//内存分配失败
	}
	node->data = data;//保存数据
	node->next = head;//指向头指针所指结点
	head = node;
	return head;
}

ChainListType* ChainListFind(ChainListType* head, char* key)
{
	ChainListType* h;
	h = head;//保存链表头指针
	while (h)//若结点有效，则进行查找
	{
		if (strcmp(h->data.key, key) == 0)//若结点关键字与传入关键字相同
			return h;//返回该结点的指针
		h = h->next;//处理下一结点
	}
	return NULL;
}

int ChainListDelete(ChainListType* head, char* key)
{
	ChainListType* node, * h;//node用来保存删除结点的前一结点
	node = h = head;
	while (h)
	{
		if (strcmp(h->data.key, key) == 0)//找到关键字，执行删除操作
		{
			node->next = h->next;//使前一结点指向当前结点的下一结点
			free(h);//释放内存
			return 1;
		}
		else {
			node = h;//指向当前结点
			h = h->next;
		}
	}
