```C++
struct Base1						
{						
public:						
    virtual void Fn_1()						
    {						
        printf("Base1:Fn_1...\n");						
    }						
    virtual void Fn_2()						
    {						
        printf("Base1:Fn_2...\n");						
    }						
};						
struct Base2						
{						
public:						
    virtual void Fn_3()						
    {						
        printf("Base2:Fn_3...\n");						
    }						
    virtual void Fn_4()						
    {						
        printf("Base2:Fn_4...\n");						
    }						
};						
struct Sub:Base1,Base2						
{						
public:						
    virtual void Fn_5()						
    {						
        printf("Sub:Fn_5...\n");						
    }						
    virtual void Fn_6()						
    {						
        printf("Sub:Fn_6...\n");						
    }						
};						
int main(int argc, char* argv[])						
{						
	//查看 Sub 的虚函数表					
    Sub sub;						

	//通过函数指针调用函数，验证正确性					
    typedef void(*pFunction)(void);						

	//对象的前四个字节是第一个Base1的虚表					
	printf("Sub 的虚函数表地址为：%x\n",*(int*)&sub);					

	pFunction pFn;					

	for(int i=0;i<6;i++)					
	{					
		int temp = *((int*)(*(int*)&sub)+i);				
		if(temp == 0)				
		{				
			break;			
		}				
		pFn = (pFunction)temp;				
		pFn();				
	}					
	//对象的第二个四字节是Base2的虚表					
	printf("Sub 的虚函数表地址为：%x\n",*(int*)((int)&sub+4));					

	pFunction pFn1;					

	for(int k=0;k<2;k++)					
	{					
		int temp = *((int*)(*(int*)((int)&sub+4))+k);				
		pFn1 = (pFunction)temp;				
		pFn1();				
	}					

	return 0;					
}						

