# 模板

例如当设计了一个算法后，暂时不知道需要传入运算的数据类型，就可以用模板代替参数类型
模板生成出来汇编代码和源代码一摸一样
ps: 向左移一位就是除以2，右移一位就是乘以2，位移运算更加高效

以下用一个算法为了加强通用性举例
```C++
/// <summary>
/// 模板
/// </summary>
template<class T>
//冒泡排序算法
void Sort(T arr, int length)
{
	for (int i=0;i<length-1;i++)
	{
		for (int j = 0;j<length-1-i;j++)
		{
			if (arr[j]>arr[j+1])
			{
				int temp = arr[j + 1];
				arr[j + 1] = arr[j];
				arr[j] = temp;
			}
		}
	}
}
//二分法查找
template<class T,class E>
int Find(T arr,int nlength,E nElement )
{
	int nBegin = 0, nEnd = nlength - 1, Idenx;
	while (nBegin <= nEnd)
	{
		Idenx = (nBegin+nEnd) / 2;//(nlength) >> 1
		if (nElement > arr[Idenx])
		{
			nBegin = Idenx + 1;
		}
		else if (nElement < arr[Idenx])
		{
			nEnd = Idenx - 1;
		}
		else
		{
			printf("Find Success: [Idenx]=%d,[Value]=%d\n", Idenx, arr[Idenx]);
			return Idenx;
		}
	}
	return -1;
}
void TestAlgorithm()
{
	char arr[] = { 2,6,1,3,8,9,4,12,11,10 };
	int length;
	char nElement = {10};
	length = sizeof(arr) / sizeof(char);
	Sort(arr, length);
	for (int i = 0; i < 10; i++)
	{
		printf("%d\n", arr[i]);
	}

	Find(arr, length, nElement);
	printf("******************************模板template<>**********************************\n");
}
```

# 引用类型-友元函数-运算符重载
引用：相当于取别名
指针的参数传递和引用的参数传递汇编代码完全一样，但是引用更安全，不像指针一样可以乱指，因为引用不能重新赋值地址，这是由编译器维护的
而且使用指针类型进行参数存传递和变量是一样的，调用函数的手看出出来
如下示例代码
```C++
/// <summary>
/// 引用类型
/// </summary>
struct BaseX
{
	int x;
	int y;
	BaseX(int x, int y)
	{
		this->x = x;
		this->y = y;
	}
};
void PrintByPoint(BaseX* pb)
{
	printf("PrintByPoint指针可以为所欲为:%d %d\n", pb->x, pb->y);
	pb = (BaseX*)0x401000;//指针可以为所欲为
	printf("PrintByPoint指针可以为所欲为:%d %d\n", pb->x, pb->y);
}
void PrintByRef(BaseX& refb, BaseX* pb)//为了避免出现这种情况，可以将refb声明为const常量，不可修改：void PrintByRef(const Base& refb)				
{
	printf("PrintByRef引用:%d %d\n", refb.x, refb.y);
	BaseX b1(21, 22);
	//&refb = b1  //引用不能重新赋值地址
	refb = b1;
	printf("PrintByRef引用:%d %d\n", refb.x, refb.y);
	printf("PrintByRef指针可以为所欲为:%d %d\n",pb->x,pb->y);

}
void TestQuote()
{
	BaseX base(1, 2);
	PrintByPoint(&base);
	PrintByRef(base, &base);
}
```


