```c
//凯撒密码
int add()
{
	char a[20] = { 0 };
	int b = 0;
	int c = 0;
	printf("输入密文：\n");
	scanf("%s", a);
	c = strlen(a);
	printf("输入密钥：\n");
	scanf("%d", &b);
	for (int i = 0; i < c; i++)
	{
		if ((a[i] >= 'a' && a[i] <= 'z') || (a[i] >= 'A' && a[1] <= 'Z'))
		{
			if ((a[i] >= ('Z' - b + 1) && a[i] <= 'Z') || (a[i] >= ('z' - b + 1) && a[i] <= 'z'))
			{
				a[i] = a[i] - (26 - b);
			}
			else
			{
				a[i] = a[i] + b;
			}

		}
		printf("%c", a[i]);
	}
	printf("\n");
	return 0;
}
int main() 
{
	add(1);
	system("pause");
}
